"""Move a cloud of unit-mass particles under mutual gravity on the GPU.

Usage: python main.py <input-file>

Input:  "<count> <steps> <dt>" followed by count lines of "<x> <y> <vx> <vy>".
Output: CENTER, MOMENTUM, KINETIC and SPREAD lines (six decimals each).
"""

import sys

import numpy as np
import wgpu

WORKGROUP_SIZE = 64

# Kernel 1: acceleration from the step's starting positions, then v += a * dt.
# Only velocities are written, so every invocation reads the same positions.
VELOCITY_SHADER = f"""
struct Params {{
    count: u32,
    dt: f32,
    _pad0: u32,
    _pad1: u32,
}};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> pos: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read_write> vel: array<vec2<f32>>;

@compute @workgroup_size({WORKGROUP_SIZE})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {{
    let i = gid.x;
    if (i >= params.count) {{
        return;
    }}
    let pi = pos[i];
    var acc = vec2<f32>(0.0, 0.0);
    for (var j: u32 = 0u; j < params.count; j = j + 1u) {{
        if (j == i) {{
            continue;
        }}
        let d = pos[j] - pi;
        let r2 = dot(d, d) + 0.01;
        acc = acc + d / (r2 * sqrt(r2));
    }}
    vel[i] = vel[i] + acc * params.dt;
}}
"""

# Kernel 2: p += v * dt using the freshly updated velocity.
POSITION_SHADER = f"""
struct Params {{
    count: u32,
    dt: f32,
    _pad0: u32,
    _pad1: u32,
}};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read> vel: array<vec2<f32>>;

@compute @workgroup_size({WORKGROUP_SIZE})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {{
    let i = gid.x;
    if (i >= params.count) {{
        return;
    }}
    pos[i] = pos[i] + vel[i] * params.dt;
}}
"""


def read_input(path):
    with open(path, "r") as f:
        tokens = f.read().split()
    if len(tokens) < 3:
        raise ValueError("input must start with '<count> <steps> <dt>'")
    count = int(float(tokens[0]))
    steps = int(float(tokens[1]))
    dt = float(tokens[2])
    fields = tokens[3 : 3 + 4 * count]
    if len(fields) < 4 * count:
        raise ValueError(f"expected {count} particle lines")
    data = np.array([float(t) for t in fields], dtype=np.float64).reshape(count, 4)
    return count, steps, dt, data[:, 0:2].copy(), data[:, 2:4].copy()


def simulate_gpu(count, steps, dt, pos, vel):
    """Run all steps on the GPU; return final (pos, vel) as float64 arrays."""
    if steps <= 0 or count <= 0:
        return pos, vel

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    usage_rw = (
        wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC | wgpu.BufferUsage.COPY_DST
    )
    pos_buf = device.create_buffer_with_data(
        data=np.ascontiguousarray(pos, dtype=np.float32).tobytes(), usage=usage_rw
    )
    vel_buf = device.create_buffer_with_data(
        data=np.ascontiguousarray(vel, dtype=np.float32).tobytes(), usage=usage_rw
    )
    params = np.zeros(4, dtype=np.uint32)
    params[0] = count
    params[1] = np.array([dt], dtype=np.float32).view(np.uint32)[0]
    params_buf = device.create_buffer_with_data(
        data=params.tobytes(), usage=wgpu.BufferUsage.UNIFORM
    )

    def make_pipeline(code, pos_type, vel_type):
        layout = device.create_bind_group_layout(
            entries=[
                {
                    "binding": 0,
                    "visibility": wgpu.ShaderStage.COMPUTE,
                    "buffer": {"type": wgpu.BufferBindingType.uniform},
                },
                {
                    "binding": 1,
                    "visibility": wgpu.ShaderStage.COMPUTE,
                    "buffer": {"type": pos_type},
                },
                {
                    "binding": 2,
                    "visibility": wgpu.ShaderStage.COMPUTE,
                    "buffer": {"type": vel_type},
                },
            ]
        )
        pipeline = device.create_compute_pipeline(
            layout=device.create_pipeline_layout(bind_group_layouts=[layout]),
            compute={"module": device.create_shader_module(code=code), "entry_point": "main"},
        )
        bind_group = device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": params_buf, "offset": 0, "size": params_buf.size}},
                {"binding": 1, "resource": {"buffer": pos_buf, "offset": 0, "size": pos_buf.size}},
                {"binding": 2, "resource": {"buffer": vel_buf, "offset": 0, "size": vel_buf.size}},
            ],
        )
        return pipeline, bind_group

    read_only = wgpu.BufferBindingType.read_only_storage
    read_write = wgpu.BufferBindingType.storage
    vel_pipeline, vel_group = make_pipeline(VELOCITY_SHADER, read_only, read_write)
    pos_pipeline, pos_group = make_pipeline(POSITION_SHADER, read_write, read_only)

    groups = (count + WORKGROUP_SIZE - 1) // WORKGROUP_SIZE
    encoder = device.create_command_encoder()
    for _ in range(steps):
        # Separate passes guarantee the velocity kernel finishes before positions move.
        for pipeline, bind_group in ((vel_pipeline, vel_group), (pos_pipeline, pos_group)):
            cpass = encoder.begin_compute_pass()
            cpass.set_pipeline(pipeline)
            cpass.set_bind_group(0, bind_group)
            cpass.dispatch_workgroups(groups, 1, 1)
            cpass.end()
    device.queue.submit([encoder.finish()])

    pos_out = np.frombuffer(device.queue.read_buffer(pos_buf), dtype=np.float32)
    vel_out = np.frombuffer(device.queue.read_buffer(vel_buf), dtype=np.float32)
    return (
        pos_out.reshape(count, 2).astype(np.float64),
        vel_out.reshape(count, 2).astype(np.float64),
    )


def fmt(x):
    s = f"{x:.6f}"
    return "0.000000" if s == "-0.000000" else s


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    count, steps, dt, pos, vel = read_input(argv[1])
    pos, vel = simulate_gpu(count, steps, dt, pos, vel)

    center = pos.mean(axis=0)
    momentum = vel.sum(axis=0)
    kinetic = float(np.sum(vel * vel) / 2.0)
    spread = float(np.sqrt(np.mean(np.sum((pos - center) ** 2, axis=1))))

    print(f"CENTER {fmt(center[0])} {fmt(center[1])}")
    print(f"MOMENTUM {fmt(momentum[0])} {fmt(momentum[1])}")
    print(f"KINETIC {fmt(kinetic)}")
    print(f"SPREAD {fmt(spread)}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

